function [cap] = optimisation_cap2(jour,h)
%renvoie une liste de 24 cap pour optimiser la puissance pendant une
%journee (24h) avec comme parametre de definition le jour pendant lequel on
%vole
%Donnees planeur
M = 350; %masse maximal [kg]
Ca = 35.7 ; % charge alaire [kg/m2]
e = 15 ; % envergure [m]
L =6.20; %longueur[m]
S =9.5; %surface alaire [m2]
lbd= 23; %allongement
fmax= 34; % finesse max
ki= 1/(pi*lbd); % car portance elliptique
Cx0=1/(4*ki*fmax*fmax);
Cxfmax= 2*Cx0;
Czfmax = power((Cx0/ki), 0.5);
latitude_deg=43.16;%position Salon de provence
%modele atmosphere
rho0 = 1.225; %kg.m-3
P0= 101325; %Pa
T0=288.15; %K
Th = 0.0065;
g=9.81;
rho = rho0*power(1+(Th/T0)*h,-4.26);
Ph = P0 * power(1+(Th/T0)*h,-3.26);
%surface du planeur
S1 = 0.98; S2 = 0.61; S3 = 3.1;
S5 = (0.30+0.42)*1.05; S6 = (0.26+0.45)*0.75;
surface_totale=S1+S2+S3+S5+S6;
N=5; %nombre d'increments
cap_test = transpose(2*pi/N*[0:N-1]);
cap=[]; Puissance_solaire=[]; P=[]; Heure=[];
for h = 0:23
Heure = [Heure; h];
if Modele_eclairement_solaire_3(P0,Ph,jour,h,latitude_deg,0,0,0)==0
cap = [cap, 300]; P = [P zeros(N,1)]; Puissance_solaire = [Puissance_solaire, 0];
else
p1 = Modele_eclairement_solaire_3(P0,Ph,jour,h,45,atan(0.42),cap,0);
p2 = Modele_eclairement_solaire_3(P0,Ph,jour,h,45,atan(0.11),cap,0);
p3 = Modele_eclairement_solaire_3(P0,Ph,jour,h,45,atan(0.17),cap,0);
p5 = Modele_eclairement_solaire_3(P0,Ph,jour,h,45,0,cap,0);
p6 = Modele_eclairement_solaire_3(P0,Ph,jour,h,45,pi/2,cap,0);
P = [P p1*S1 + p2*S2 + p3*S3 + p5*S5 + p6*S6];
[max_p,indice_max]=max(P(:,h));
cap = [cap, indice_max*2*pi/N];
end
end
end

function [pente]=pente_fonction_puissance2(Pu)
%renvoie la valeur de la pente en fonction de la puissance du moteur
M = 350; Ca = 35.7; e = 15; L = 6.20; S = 9.5; lbd = 23;
h = 500; fmax = 34;
ki = 1/(pi*lbd); Cx0=1/(4*ki*fmax^2); Cxfmax=2*Cx0;
Czfmax = power((Cx0/ki), 0.5); g=9.81;
rho0 = 1.225; T0=288.15; Th=0.0065;
rho = rho0*power((1+(Th/T0)*h),-4.26);
Vfmax = sqrt(2*M*g/(rho*S*Czfmax));
pente = Pu/(Vfmax*M*g) - 0.5*rho*S*Vfmax^2*Cxfmax/(M*g);
end

function [endurance] = optimisation_endurance1(Pu)
%renvoie l'endurance en temps du planeur (hypothese : energie solaire
%totale disponible des le debut du vol)
M = 350; S = 9.5; lbd = 23; h = 500; h_vent_arriere = 300;
fmax = 34; Va = 87/3.6;
ki = 1/(pi*lbd); Cx0=1/(4*ki*fmax^2); Czfmax = power((Cx0/ki), 0.5); g=9.81;
jour = 175; %journee de vol (175 = meilleur, 357 = pire)
rho0 = 1.225; T0=288.15; Th=0.0065;
rho = rho0*power((1+(Th/T0)*h),-4.26);
Vfmax = sqrt(2*M*g/(rho*S*Czfmax));
m_ajoutee = 50; m_moteur = 3.3 * Pu*10^-3/0.8; m_batterie = 46 - m_moteur;
Puissance_solaire = optimisation_cap1(jour,h,24);
Energie_solaire = integration(Puissance_solaire);
Capacite_batterie = 190*m_batterie; Capacite_totale = Capacite_batterie + Energie_solaire;
Duree_fonctionnement_moteur = Capacite_totale/(Pu/0.8);
finesse_optimisee = -1/pente_fonction_puissance2(Pu);
Distance_possible = abs(finesse_optimisee)*(h - h_vent_arriere);
Duree_vol_possible = Distance_possible / (Vfmax*3600);
if Duree_vol_possible <= Duree_fonctionnement_moteur
endurance = Duree_vol_possible;
else
d_moteur = Duree_fonctionnement_moteur*Vfmax*3600;
h_descendue = d_moteur/finesse_optimisee;
d_suivante = fmax*(h - h_vent_arriere - h_descendue);
duree_suivante = d_suivante/(Vfmax*3600);
endurance = Duree_fonctionnement_moteur + duree_suivante;
end
end

function [endurance] = optimisation_endurance2(Pu)
%second modele : l'energie solaire est distribuee pas a pas dans le temps
%(et non disponible en totalite des le debut du vol)
N = 500; dt = 24/N;
M = 350; S = 9.5; lbd = 23; h = 500; h_vent_arriere = 300; fmax = 34;
ki = 1/(pi*lbd); Cx0=1/(4*ki*fmax^2); Czfmax = power((Cx0/ki), 0.5); g=9.81;
jour = 357;
rho0 = 1.225; T0=288.15; Th=0.0065;
rho = rho0*power((1+(Th/T0)*h),-4.26);
Vfmax = sqrt(2*M*g/(rho*S*Czfmax));
m_ajoutee = 50; m_moteur = 3.3*Pu*10^-3/0.8; m_batterie = 46 - m_moteur;
Capacite_batterie = 190*m_batterie; Capacite_totale = Capacite_batterie;
cap = optimisation_cap2(jour,h);
Puissance_solaire = optimisation_cap1(jour,h,N);
t0 = debut_de_vol(Puissance_solaire);
Test_charge = 0; altitude = h; temps_de_fin=[];
for p = 1:N
if Puissance_solaire(p)~=0 && altitude > 300
if Test_charge==0
if Capacite_totale > 0
Capacite_totale = Capacite_totale - (Pu/0.8)*dt + Puissance_solaire(p)*dt;
altitude = altitude - Vfmax*3600*dt*abs(pente_fonction_puissance2(Pu));
else
Test_charge = 1;
end
else
if Capacite_totale < Capacite_batterie
altitude = altitude - Vfmax*3600*fmax*dt;
Capacite_totale = Capacite_totale + Puissance_solaire(p)*dt;
else
Test_charge = 0;
end
end
elseif Puissance_solaire(p)~=0
temps_de_fin = [temps_de_fin, p*24/N];
end
end
if isempty(temps_de_fin)
endurance = fin_de_vol(Puissance_solaire) - t0;
else
endurance = temps_de_fin(1) - t0;
end
end

%Annexe 10 : calcul de l'heure de depart optimal
Pu = [1000:2500];
jour = 175;
Puissance_solaire = optimisation_cap1(jour,500,500);
t0 = debut_de_vol(Puissance_solaire);
tf = fin_de_vol(Puissance_solaire);
maximum = 0; decollage = 0;
for j = floor(t0)+1:floor(tf)
endurance_opt=[];
for k = 1000:2500
endurance_opt = [endurance_opt, optimisation_endurance3(k, j)];
end
max_endurancej = max(endurance_opt);
if max_endurancej > maximum
maximum = max_endurancej; decollage = j;
end
end
